'use strict';
const C=BittleCore,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',home:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',route:'M5 5h10a5 5 0 0 1 0 10H9 M5 2v6 M2 5h6 M9 12l-3 3 3 3',pin:'M12 22s8-8 8-14a8 8 0 1 0-16 0c0 6 8 14 8 14z M9 8a3 3 0 1 0 6 0a3 3 0 1 0-6 0',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3C8 1 2 9 6 16s14 2 14-13z M4 21l11-12',stop:'M6 6h12v12H6z',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',pause:'M8 5v14 M16 5v14',play:'M7 4l14 8-14 8z',battery:'M2 6h17v12H2z M22 10v4 M5 9h10v6H5z',wifi:'M3 8a15 15 0 0 1 18 0 M6 12a10 10 0 0 1 12 0 M9 16a5 5 0 0 1 6 0 M12 20h.01',egg:'M20 15c0 10-16 10-16 0C4 8 9 2 12 2s8 6 8 13z',water:'M12 2S4 11 4 16a8 8 0 0 0 16 0c0-5-8-14-8-14z',door:'M5 21V3h14v18 M3 21h18 M14 12h1',fence:'M5 3v18 M12 3v18 M19 3v18 M3 8h18 M3 16h18',select:'M5 3l15 9-7 2-3 7z',undo:'M8 4L3 9l5 5 M3 9h12a6 6 0 0 1 0 12',redo:'M16 4l5 5-5 5 M21 9H9a6 6 0 0 0 0 12',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',check:'M4 12l5 5L20 6',edit:'M4 16L16 4l4 4L8 20H4z',camera:'M3 7h5l2-3h4l2 3h5v14H3z M8 14a4 4 0 1 0 8 0a4 4 0 1 0-8 0',zone:'M3 3h18v18H3z M3 3l18 18 M3 11l10 10 M11 3l10 10',reset:'M3 10a9 9 0 1 1 1 9 M3 3v7h7'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;}
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const navs=[['overzicht','grid','Overzicht'],['terrein','home','Mijn kippenhok'],['patrouilles','route','Patrouilles'],['buurt','pin','In de buurt'],['activiteit','clock','Activiteit']];$('#nav').innerHTML=navs.map(([id,i,n])=>`<a href="#${id}" data-page="${id}">${icon(i)}<span>${n}</span>${id==='buurt'?'<b class="nav-count">2</b>':''}</a>`).join('');
let data=C.initial(),storageOK=true;try{const raw=localStorage.getItem('bittle-landlicht-v1');if(raw)data=C.validate(JSON.parse(raw));}catch(e){storageOK=false;}
let page='overzicht',view=null,selection=null,tool='select',draft=[],undo=[],redo=[],drag=null,toastTimer,zoom=1;
let robot={x:300,y:420,heading:0,moving:false},motion={mode:'paused',path:[],index:0,routeId:data.routes[0]?.id,routeIndex:0,kind:'patrol',checking:0},last=performance.now(),lastSample=0;
const statuses={paused:'Gepauzeerd',stopped:'Gestopt',docked:'Bij het dock',dock:'Terug naar dock',eggs:'Naar het legnest',water:'Naar de drinkbak',checking:'Controle bezig',done:'Controle afgerond',blocked:'Route geblokkeerd',editor:'Kaart bewerken'};
function status(){return motion.mode==='patrol'?`Patrouille · ${data.routes.find(r=>r.id===motion.routeId)?.name||'Tuin'}`:statuses[motion.mode]||'Gereed';}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3600);}
function persist(){try{localStorage.setItem('bittle-landlicht-v1',JSON.stringify(data));storageOK=true;$('#save-status').innerHTML=icon('check')+' Opgeslagen';}catch(e){storageOK=false;$('#save-status').textContent='Opslaan niet beschikbaar';}}
function snapshot(){undo.push(JSON.stringify(data));if(undo.length>40)undo.shift();redo=[];}
function log(label,detail=''){data.events=data.events||[];data.events.unshift({label,detail,time:Date.now()});data.events=data.events.slice(0,80);persist();}
function age(t){const n=Math.max(0,Math.floor((Date.now()-t)/60000));return n<1?'nu':n<60?`${n} min`:`${Math.floor(n/60)} u`;}
function stamp(t){return `<span class="freshness" title="Bijgewerkt ${age(t)} geleden" aria-label="Bijgewerkt ${age(t)} geleden">${icon('clock')}${age(t)}</span>`;}
function eggs(){return `<div class="eggs-visual" aria-label="${data.eggs} eieren">${Array.from({length:Math.min(data.eggs,6)},(_,i)=>`<span class="egg" style="--turn:${[-12,5,16,-5,10,-10][i]}deg;--i:${i}"></span>`).join('')}${data.eggs===0?'<span class="empty-nest">Leeg nest</span>':data.eggs>6?`<span class="egg-more">+${data.eggs-6}</span>`:''}</div>`;}
function stats(){return `<div class="summary-grid"><section class="summary eggs-card"><div class="card-label">In het nest ${stamp(data.eggTime)}</div><div class="eggs-content">${eggs()}<button class="icon-button" data-action="edit-eggs" aria-label="Aantal eieren aanpassen" title="Aantal aanpassen">${icon('edit')}</button></div><div class="summary-bottom"><strong>${data.eggs} eieren</strong><button class="text-button" data-action="collect" ${data.eggs===0?'disabled':''}>Verzameld ${icon('arrow')}</button></div></section><section class="summary door-card"><div class="card-label">Hokdeur ${stamp(data.doorTime)}</div><div class="door-visual"><div class="door-frame"><div class="door-panel"><i></i></div></div><span class="shield-check">${icon('check')}</span></div><div class="summary-bottom"><strong>Gesloten</strong><span class="subdued">Deursensor</span></div></section><section class="summary robot-summary"><div class="card-label">Bittle X <span class="telemetry" title="78% batterij · verbonden">${icon('wifi')}${icon('battery')}<span>78%</span></span></div><div class="robot-mini"><div class="robot-body"><i></i><b></b><span></span></div><div class="robot-leg l1"></div><div class="robot-leg l2"></div><div class="robot-leg l3"></div><div class="robot-leg l4"></div></div><div class="summary-bottom"><strong class="robot-status">${esc(status())}</strong><span class="live-dot"></span></div></section></div>`;}
function canvasCard(editor=false){return `<section class="terrain-card ${editor?'editor-map':''}"><div class="terrain-top"><div><span class="eyebrow">${editor?'TERREINEDITOR':'TERREIN'}</span><h2>Mijn tuin</h2></div>${editor?'<span class="local-label">Handmatig</span>':`<a href="#terrein" class="map-link">Aanpassen ${icon('arrow')}</a>`}</div><div class="canvas-wrap"><canvas id="terrain-canvas" tabindex="0" aria-label="Tuinplattegrond${editor?', selecteer en sleep objecten of teken een route':''}"></canvas><div class="map-zoom"><button data-action="zoom-out" aria-label="Uitzoomen">−</button><button data-action="zoom-reset" aria-label="Zoom herstellen">${icon('select')}</button><button data-action="zoom-in" aria-label="Inzoomen">+</button></div>${editor?'<div class="tool-hint" id="tool-hint">Selecteer een object om het te bewerken</div>':`<div class="map-control"><span class="moving-dot"></span><span>Bittle X</span><button id="toggle-motion" data-action="toggle" aria-label="Patrouille starten of pauzeren">${icon(robot.moving?'pause':'play')}</button><button data-action="dock" title="Terug naar dock" aria-label="Terug naar dock">${icon('home')}</button></div>`}</div></section>`;}
function quickActions(){return `<section class="quick-card"><div class="section-heading"><h2>Snelle acties</h2><span class="tiny-label">BITTLE</span></div><button data-action="eggs"><span class="action-icon">${icon('egg')}</span><span>Check de eieren<small>Legnest</small></span>${icon('arrow')}</button><button data-action="water"><span class="action-icon water">${icon('water')}</span><span>Check drinkbak<small>Watervoorraad</small></span>${icon('arrow')}</button><button data-action="patrol"><span class="action-icon">${icon('route')}</span><span>Start patrouille<small>${esc(data.routes[0]?.name||'Nog geen route')}</small></span>${icon('arrow')}</button></section>`;}
function neighborhoodMap(){return `<div class="neighborhood-map"><svg viewBox="0 0 600 240" role="img" aria-label="Fictieve buurtkaart met twee voswaarnemingen"><defs><pattern id="lots" width="70" height="55" patternUnits="userSpaceOnUse"><rect x="8" y="8" width="44" height="33" rx="4" fill="#dce3d0" stroke="#ccd6c0"/><rect x="18" y="16" width="17" height="12" rx="1" fill="#c5bda7"/></pattern></defs><rect width="600" height="240" fill="#e8eddf"/><rect width="600" height="240" fill="url(#lots)"/><path d="M-30 230L190 80 370 150 640 30 M180 0l20 260 M0 50l600 140" fill="none" stroke="#fdfcf3" stroke-width="18"/><path d="M470 -10Q380 90 520 250" fill="none" stroke="#b9d0c8" stroke-width="18"/><circle cx="290" cy="125" r="46" fill="#4f79551a"/><circle cx="290" cy="125" r="7" fill="#3f6649" stroke="white" stroke-width="4"/><g fill="#b67946" stroke="#fffdf6" stroke-width="3"><circle cx="130" cy="100" r="14"/><circle cx="410" cy="190" r="14"/></g><g fill="white" font-size="12" text-anchor="middle"><text x="130" y="104">1</text><text x="410" y="194">2</text></g></svg><span>Voorbeeldkaart</span></div>`;}
function events(limit=20){return (data.events||[]).slice(0,limit).map(e=>`<li><span class="event-dot"></span><div><strong>${esc(e.label)}</strong><small>${esc(e.detail||'')}</small></div><time>${new Date(e.time).toLocaleTimeString('nl-BE',{hour:'2-digit',minute:'2-digit'})}</time></li>`).join('')||'<li>Nog geen activiteit</li>';}
function dashboard(){return `${stats()}<div class="overview-main">${canvasCard()}<div class="overview-side">${quickActions()}<section class="connection-card"><span class="camera-icon">${icon('camera')}</span><div><h3>Camera</h3><small>Wacht op koppeling</small></div><span class="offline-dot"></span></section></div></div><div class="overview-bottom"><section class="panel neighborhood-preview"><div class="section-heading"><h2>In de buurt <span class="count-badge">2</span></h2><a href="#buurt" class="text-button">Bekijken ${icon('arrow')}</a></div>${neighborhoodMap()}<div class="neighborhood-note"><span class="fox-dot"></span> Vos gespot <span>800 m · 1 u</span></div></section><section class="panel"><div class="section-heading"><h2>Activiteit</h2><a href="#activiteit" class="text-button">Alles ${icon('arrow')}</a></div><ol class="event-list">${events(3)}</ol></section></div>`;}
function editor(){return `<div class="editor-toolbar"><div class="tool-group"><button class="button selected" data-tool="select">${icon('select')} Selecteren</button><button class="button" data-tool="route">${icon('route')} Route tekenen</button><button class="button" data-tool="zone">${icon('zone')} Verboden zone</button></div><div class="tool-group"><button class="icon-button" data-action="undo" title="Ongedaan maken" aria-label="Ongedaan maken">${icon('undo')}</button><button class="icon-button" data-action="redo" title="Opnieuw" aria-label="Opnieuw">${icon('redo')}</button><button class="icon-button" data-action="export" title="Kaart exporteren" aria-label="Kaart exporteren">${icon('download')}</button><button class="icon-button" data-action="import" title="Kaart importeren" aria-label="Kaart importeren">${icon('upload')}</button></div></div><div class="builder-layout"><div>${canvasCard(true)}<div class="drawing-controls" id="drawing-controls" hidden><span id="point-count">0 punten</span><label><input id="route-closed" type="checkbox" checked> Gesloten ronde</label><button class="button" data-action="remove-point">Laatste punt weg</button><button class="button primary" data-action="finish-drawing">Opslaan</button><button class="text-button" data-action="cancel-drawing">Annuleren</button></div><div class="object-library"><div class="section-heading"><h3>Toevoegen</h3><span>Kies, plaats, versleep</span></div><div class="library-grid">${Object.entries(C.TYPES).map(([key,v])=>`<button data-tool="${key}"><span class="library-art ${key}">${icon({coop:'home',nest:'egg',water:'water',plant:'leaf',door:'door',fence:'fence',dock:'battery'}[key])}</span>${v.name}</button>`).join('')}</div></div></div><aside class="inspector"><div id="inspector-content"></div><div class="object-list-heading">ONDERDELEN <span>${data.objects.length}</span></div><div id="object-list"></div></aside></div>`;}
function missions(){return `<div class="page-intro"><p>Routes en controles voor je tuin.</p><a href="#terrein" class="button primary">${icon('plus')} Route tekenen</a></div><div class="mission-layout"><div class="route-cards">${data.routes.map((r,i)=>`<section class="route-card"><div class="route-art"><svg viewBox="0 0 300 130"><path d="M20 100Q30 10 100 35T270 30" fill="none" stroke="#bdcba7" stroke-width="34" stroke-linecap="round"/><polyline points="${r.points.map(p=>`${p.x*.28},${p.y*.2}`).join(' ')}" fill="none" stroke="#456541" stroke-width="2" stroke-dasharray="5 4"/></svg><span>0${i+1}</span></div><div class="route-info"><h2>${esc(r.name)}</h2><small>${r.points.length} punten · ${r.closed?'Gesloten ronde':'Enkele route'}</small><button class="button primary" data-route-start="${esc(r.id)}">${icon('play')} Starten</button></div></section>`).join('')||'<div class="panel">Teken je eerste route in Mijn kippenhok.</div>'}</div>${quickActions()}</div><section class="panel mission-state"><span class="live-dot"></span><strong class="robot-status">${esc(status())}</strong><button class="button" data-action="toggle">${icon('pause')} Pauzeren / hervatten</button><button class="button" data-action="dock">${icon('home')} Naar dock</button></section>`;}
function buurt(){return `<div class="page-intro"><p>Waarnemingen rond je tuin.</p><span class="connection-pill">Buurtbron niet gekoppeld</span></div><section class="panel buurt-full">${neighborhoodMap()}<div class="sighting-row"><span class="sighting-number">1</span><div><h3>Vos bij de veldweg</h3><small>Voorbeeldmelding · onbevestigd</small></div><span>800 m</span><span>${icon('clock')} 1 u</span></div><div class="sighting-row"><span class="sighting-number">2</span><div><h3>Vos aan de bosrand</h3><small>Voorbeeldmelding · onbevestigd</small></div><span>1,4 km</span><span>${icon('clock')} 8 u</span></div></section>`;}
function render(){view?.destroy();page=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overzicht';if(page==='terrein'){motion.mode='editor';robot.moving=false;}selection=null;tool='select';draft=[];zoom=1;const name=navs.find(n=>n[0]===page)[2];$('#page-title').textContent=name;$('#crumb').textContent=name;document.title=`Bittle — ${name}`;document.querySelectorAll('#nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page').innerHTML=page==='overzicht'?dashboard():page==='terrein'?editor():page==='patrouilles'?missions():page==='buurt'?buurt():`<section class="panel activity-page"><div class="section-heading"><h2>Vandaag</h2><span>${(data.events||[]).length} gebeurtenissen</span></div><ol class="event-list">${events(80)}</ol></section>`;const canvas=$('#terrain-canvas');if(canvas){view=new TerrainView(canvas,()=>data,{editor:page==='terrein',robot:()=>robot});view.samples=trailHistory;if(page==='terrein')bindEditor(canvas);}if(page==='terrein')inspector();syncStatus();}
function syncStatus(){document.querySelectorAll('.robot-status').forEach(e=>e.textContent=status());const b=$('#toggle-motion');if(b){b.innerHTML=icon(robot.moving?'pause':'play');b.setAttribute('aria-label',robot.moving?'Pauzeren':'Patrouille starten');}}
function setPath(destination,kind){if(page==='terrein'){notify('Open Overzicht of Patrouilles om een actie te starten.');return false;}const path=C.plan(robot,destination,data);if(!path){motion.mode='blocked';robot.moving=false;syncStatus();notify('Geen vrije route. Controleer objecten en verboden zones.');return false;}motion.path=path;motion.index=0;motion.mode=kind;motion.kind=kind;robot.moving=true;syncStatus();return true;}
function startPatrol(id){const r=data.routes.find(r=>r.id===(id||motion.routeId))||data.routes[0];if(!r){notify('Teken eerst een patrouille in Mijn kippenhok.');return;}motion.routeId=r.id;motion.routeIndex=0;if(setPath(r.points[0],'patrol'))log('Patrouille gestart',r.name);}
function task(kind){const type={dock:'dock',eggs:'nest',water:'water'}[kind],o=data.objects.find(o=>o.type===type);if(!o){notify(`Plaats eerst een ${C.TYPES[type].name.toLowerCase()} op je terrein.`);return;}const p=kind==='dock'?o:C.approach(o,data);if(!p){notify('Dit onderdeel is niet bereikbaar.');return;}if(setPath(p,kind))log({dock:'Terug naar dock',eggs:'Eiercontrole gestart',water:'Watercontrole gestart'}[kind]);}
let trailHistory=[];
function tick(now){const dt=Math.min((now-last)/1000,.06);last=now;if(robot.moving&&motion.path.length){const q=motion.path[motion.index],dx=q.x-robot.x,dy=q.y-robot.y,d=Math.hypot(dx,dy),step=Math.min(d,38*dt),heading=Math.atan2(dy,dx);let da=heading-robot.heading;while(da>Math.PI)da-=Math.PI*2;while(da<-Math.PI)da+=Math.PI*2;robot.heading+=da*Math.min(1,dt*9);if(d>0){robot.x+=dx/d*step;robot.y+=dy/d*step;}if(d<1){motion.index++;if(motion.index>=motion.path.length){if(motion.mode==='patrol'){const r=data.routes.find(r=>r.id===motion.routeId);motion.routeIndex++;if(!r||(!r.closed&&motion.routeIndex>=r.points.length)){robot.moving=false;motion.mode='done';}else{motion.routeIndex%=r.points.length;setPath(r.points[motion.routeIndex],'patrol');}}else if(motion.mode==='dock'){robot.moving=false;motion.mode='docked';log('Bittle bij het dock');}else{robot.moving=false;motion.mode='checking';motion.checking=now+2500;}syncStatus();}}if(now-lastSample>80){trailHistory.push({x:robot.x,y:robot.y,t:now});lastSample=now;}}if(motion.mode==='checking'&&now>motion.checking){motion.mode='done';if(motion.kind==='eggs'){data.eggTime=Date.now();log('Legnest bezocht','Demo · telling niet automatisch aangepast');}else log('Drinkbak bezocht','Demo · geen sensormeting');notify('Controle afgerond');syncStatus();}trailHistory=trailHistory.filter(p=>now-p.t<120000);if(view)view.samples=trailHistory;requestAnimationFrame(tick);}
function inspector(){const o=data.objects.find(o=>o.id===selection),r=data.routes.find(r=>r.id===selection)||data.zones.find(r=>r.id===selection);$('#inspector-content').innerHTML=o?`<span class="eyebrow">EIGENSCHAPPEN</span><h2>${C.TYPES[o.type].name}</h2><label>Naam<input id="object-name" value="${esc(o.name)}" maxlength="60"></label><div class="field-pair"><label>X<input type="number" id="object-x" min="30" max="930" value="${Math.round(o.x)}"></label><label>Y<input type="number" id="object-y" min="30" max="570" value="${Math.round(o.y)}"></label></div><div class="field-pair"><label>Breedte<input type="number" id="object-w" min="10" max="400" value="${o.w}"></label><label>Diepte<input type="number" id="object-h" min="8" max="300" value="${o.h}"></label></div><label>Rotatie <span>${o.rotation}°</span><input type="range" id="object-rotation" min="0" max="360" step="5" value="${o.rotation}"></label><div class="inspector-actions"><button class="button" data-action="duplicate">${icon('plus')} Kopie</button><button class="icon-button danger" data-action="delete" aria-label="Onderdeel verwijderen">${icon('trash')}</button></div>`:r?`<span class="eyebrow">ROUTE / ZONE</span><h2>${esc(r.name)}</h2><label>Naam<input id="route-name" value="${esc(r.name)}" maxlength="60"></label><p class="muted">${r.points.length} punten. Versleep de punten op de kaart.</p><button class="button danger" data-action="delete">${icon('trash')} Verwijderen</button>`:`<span class="eyebrow">JOUW TERREIN</span><h2>Alles op zijn plek.</h2><p class="muted">Plaats een onderdeel, versleep het op de kaart en verfijn de afmetingen hier.</p><div class="inspector-illustration">${icon('home')}${icon('leaf')}</div><span class="mapping-note">Robotmapping nog niet gekoppeld</span>`;
$('#object-list').innerHTML=[...data.objects,...data.routes,...data.zones].map(o=>`<button class="object-row ${selection===o.id?'selected':''}" data-select="${esc(o.id)}">${icon(o.type?{coop:'home',nest:'egg',water:'water',plant:'leaf',door:'door',fence:'fence',dock:'battery'}[o.type]:'route')}<span>${esc(o.name)}</span></button>`).join('');if(o)for(const key of ['name','x','y','w','h','rotation'])$('#object-'+key).onchange=e=>{let v=key==='name'?e.target.value.trim():Number(e.target.value);if(key==='name'&&!v)v=C.TYPES[o.type].name;if(key!=='name'&&(!Number.isFinite(v)||v<Number(e.target.min)||v>Number(e.target.max))){notify('Kies een waarde binnen het bereik.');inspector();return;}snapshot();o[key]=v;changed();inspector();};if(r)$('#route-name').onchange=e=>{snapshot();r.name=e.target.value.trim()||'Route';changed();inspector();};if(view)view.selected=selection;}
function changed(){trailHistory=[];persist();view?.invalidate();}
function select(id){selection=id;tool='select';setToolUI();inspector();}
function setToolUI(){document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('selected',b.dataset.tool===tool));if($('#drawing-controls'))$('#drawing-controls').hidden=!['route','zone'].includes(tool);if($('#tool-hint'))$('#tool-hint').textContent=tool==='select'?'Selecteer en versleep een onderdeel':tool==='route'?'Klik de punten van je route · Opslaan om af te ronden':tool==='zone'?'Klik de hoeken van een verboden zone':`Klik op de kaart om ${C.TYPES[tool]?.name.toLowerCase()} te plaatsen`;if(view)view.draft=draft;if($('#point-count'))$('#point-count').textContent=`${draft.length} punten`;}
function hit(p,o){const a=-o.rotation*Math.PI/180,dx=p.x-o.x,dy=p.y-o.y;return Math.abs(dx*Math.cos(a)-dy*Math.sin(a))<o.w/2+8&&Math.abs(dx*Math.sin(a)+dy*Math.cos(a))<o.h/2+8;}
function bindEditor(canvas){canvas.onpointerdown=e=>{const p=view.point(e);if(p.x<35||p.x>925||p.y<35||p.y>565)return;canvas.focus();if(tool==='route'||tool==='zone'){draft.push(p);setToolUI();return;}if(C.TYPES[tool]){snapshot();const type=tool,d=C.TYPES[type],o={id:crypto.randomUUID(),type,name:d.name,x:p.x,y:p.y,w:d.w,h:d.h,rotation:0};data.objects.push(o);changed();select(o.id);return;}const route=[...data.routes,...data.zones].find(r=>r.id===selection);if(route){const i=route.points.findIndex(q=>Math.hypot(q.x-p.x,q.y-p.y)<14);if(i>=0){snapshot();drag={route,index:i};canvas.setPointerCapture(e.pointerId);return;}}const o=[...data.objects].reverse().find(o=>hit(p,o));if(o){select(o.id);snapshot();drag={object:o,dx:p.x-o.x,dy:p.y-o.y};canvas.setPointerCapture(e.pointerId);}else{selection=null;inspector();}};canvas.onpointermove=e=>{if(!drag)return;const p=view.point(e);if(drag.object){drag.object.x=Math.max(40,Math.min(920,p.x-drag.dx));drag.object.y=Math.max(40,Math.min(560,p.y-drag.dy));}else drag.route.points[drag.index]={x:Math.max(40,Math.min(920,p.x)),y:Math.max(40,Math.min(560,p.y))};view.invalidate();};const end=()=>{if(drag){drag=null;changed();inspector();}};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onkeydown=e=>{if(e.key==='Escape'){draft=[];tool='select';setToolUI();}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const o=data.objects.find(o=>o.id===selection);if(o){e.preventDefault();snapshot();const axis=e.key.includes('Left')||e.key.includes('Right')?'x':'y',sign=e.key.includes('Left')||e.key.includes('Up')?-1:1;o[axis]=Math.max(40,Math.min(axis==='x'?920:560,o[axis]+sign*(e.shiftKey?10:2)));changed();inspector();}}};}
function finishDrawing(){const minimum=tool==='zone'?3:2;if(draft.length<minimum){notify(`Plaats minstens ${minimum} punten.`);return;}if(draft.length>150){notify('Gebruik maximaal 150 punten.');return;}snapshot();const item={id:crypto.randomUUID(),name:tool==='zone'?`Verboden zone ${data.zones.length+1}`:`Patrouille ${data.routes.length+1}`,points:C.clone(draft),closed:tool==='zone'||$('#route-closed').checked};(tool==='zone'?data.zones:data.routes).push(item);draft=[];changed();select(item.id);notify('Opgeslagen');}
function action(a){switch(a){case 'toggle':if(page==='terrein')return;if(robot.moving){robot.moving=false;motion.resume=motion.mode;motion.mode='paused';}else if(motion.path.length&&motion.index<motion.path.length&&motion.resume){motion.mode=motion.resume;robot.moving=true;}else startPatrol();syncStatus();break;case 'patrol':startPatrol();break;case 'dock':case 'eggs':case 'water':task(a);break;case 'edit-eggs':$('#egg-count').value=data.eggs;$('#egg-dialog').showModal();break;case 'collect':data.eggs=0;data.eggTime=Date.now();log('Eieren verzameld','Handmatig');render();break;case 'zoom-in':case 'zoom-out':case 'zoom-reset':zoom=a==='zoom-reset'?1:Math.max(.8,Math.min(2,zoom+(a==='zoom-in'?.2:-.2)));if(view)view.zoom=zoom;break;case 'undo':case 'redo':{const from=a==='undo'?undo:redo,to=a==='undo'?redo:undo;if(!from.length){notify('Geen wijzigingen om terug te zetten.');return;}to.push(JSON.stringify(data));data=JSON.parse(from.pop());selection=null;changed();inspector();break;}case 'delete':snapshot();data.objects=data.objects.filter(o=>o.id!==selection);data.routes=data.routes.filter(o=>o.id!==selection);data.zones=data.zones.filter(o=>o.id!==selection);selection=null;changed();inspector();break;case 'duplicate':{const o=data.objects.find(o=>o.id===selection);if(!o)return;snapshot();const copy={...o,id:crypto.randomUUID(),name:(o.name+' kopie').slice(0,60),x:Math.min(920,o.x+40),y:Math.min(560,o.y+35)};data.objects.push(copy);changed();select(copy.id);break;}case 'finish-drawing':finishDrawing();break;case 'remove-point':draft.pop();setToolUI();break;case 'cancel-drawing':draft=[];tool='select';setToolUI();break;case 'export':{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bittle-mijn-tuin.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case 'import':$('#import-file').click();break;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-tool],[data-select],[data-route-start]');if(!b)return;if(b.dataset.action)action(b.dataset.action);if(b.dataset.tool){tool=b.dataset.tool;draft=[];setToolUI();}if(b.dataset.select)select(b.dataset.select);if(b.dataset.routeStart)startPatrol(b.dataset.routeStart);});
$('#stop-button').onclick=()=>{robot.moving=false;motion.resume=motion.mode==='patrol'||motion.mode==='dock'?motion.mode:null;motion.mode='stopped';syncStatus();};$('#save-eggs').onclick=e=>{const n=Number($('#egg-count').value);if(!Number.isInteger(n)||n<0||n>24){e.preventDefault();notify('Kies een aantal van 0 tot 24.');return;}data.eggs=n;data.eggTime=Date.now();log('Eieren bijgewerkt',`${n} eieren · handmatig`);render();};$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>250000)throw Error('Bestand is te groot.');const v=C.validate(JSON.parse(await f.text()));snapshot();data=v;motion.mode='paused';robot.moving=false;changed();render();notify('Kaart geïmporteerd');}catch(err){notify(err.message);}e.target.value='';};window.addEventListener('hashchange',render);render();if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&page!=='terrein')startPatrol();requestAnimationFrame(tick);if(!storageOK)notify('Lokale opslag niet beschikbaar of vorige kaart ongeldig. Exporteer om te bewaren.');
